  4	export type KeatingCapabilityId = "learner-details" | "media" | "workspace" | "improvement" | "voice";
  5	export type CapabilityAvailability = "available" | "unavailable" | "approval-required";
  6	
  7	export interface CapabilityBundle {
  8		id: KeatingCapabilityId;
  9		title: string;
 10		description: string;
