 88	function preserveRegistrationOrder(groups: AgentTool[][]): AgentTool[] {
 89		const tools = groups.flat();
 90		const byName = new Map(tools.map((tool) => [tool.name, tool]));
 91		const ordered = TOOL_REGISTRATION_ORDER.flatMap((name) => {
 92			const tool = byName.get(name);
 93			if (!tool) return [];
 94			byName.delete(name);
 95			return [tool];
 96		});
 97		return [...ordered, ...byName.values()];
 98	}
