100	export async function createKeatingTools(
101		storage: KeatingStorage,
102		options: KeatingToolsOptions = {},
103	): Promise<AgentTool[]> {
104		const security = (options as KeatingToolsOptions & {
105			security?: {
106				executor: AuthorizedToolExecutor;
107				getContext: () => ToolExecutionContext;
108				requestConfirmation: (review: ToolConfirmationReview) => Promise<boolean>;
109			};
110		}).security;
111		const collectRealOutcomes = createOutcomeCollector(storage, options.getSessionSamples);
112		const tools = preserveRegistrationOrder([
113			createWorkspaceTools(options),
114			createMediaTools(storage),
115			createTeachingTools(storage),
116			createAssessmentTools(storage, collectRealOutcomes),
117			createImprovementTools(storage, options, collectRealOutcomes),
118		]);
119	
120		const registry = createToolRegistry(tools);
121		tools.push(
122			...createLearnerContextCapabilityTools(registry),
123			...createImprovementCapabilityTools(registry),
124			...createWorkspaceCapabilityTools(registry, options),
125		);
126	
127		if (options.speech?.settings.enabled) {
128			tools.push(createSpeechTool(options.speech.settings, options.speech.getApiKey));
129		}
130	
131		if (!security) return tools;
132		return tools.map((tool) => {
133			if (!tool.execute) return tool;
134			const execute = tool.execute.bind(tool) as (...args: any[]) => Promise<unknown>;
135			const securedTool = {
136				...tool,
137				execute: async (...args: any[]) => security.executor.executeWithTrustedConfirmation({
138					toolName: tool.name,
139					arguments: args[1],
140					context: security.getContext(),
141					run: () => execute(...args),
142					requestConfirmation: security.requestConfirmation,
143				}),
144			} as AgentTool;
145			rawToolExecutions.set(securedTool as object, execute);
146			return securedTool;
147		});
148	}

