 36	function canonical(value: unknown): string {
 37		if (value === null || typeof value !== "object") return JSON.stringify(value);
 38		if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
 39		return `{${Object.entries(value as Record<string, unknown>).sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => `${JSON.stringify(key)}:${canonical(item)}`).join(",")}}`;
