 53		async execute<T>(input: {
 54			toolName: string;
 55			arguments?: unknown;
 56			context: ToolExecutionContext;
 57			run: () => Promise<T>;
 58		}): Promise<T> {
 59			const decision = evaluateToolPermission({
 60				tool: classifyTool(input.toolName),
 61				surface: input.context.surface,
 62				provenance: input.context.provenance,
