 90				let timeout: ReturnType<typeof setTimeout> | undefined;
 91				const approved = await Promise.race([
 92					input.requestConfirmation({
 93						toolName: challenge.toolName,
 94						risk: challenge.risk,
 95						surface: input.context.surface,
 96						expiresAt: challenge.expiresAt,
 97					}),
 98					new Promise<boolean>((resolve) => { timeout = setTimeout(() => resolve(false), remainingMs); }),
 99				]);
100				if (timeout) clearTimeout(timeout);
