102					this.challenges.delete(challenge.id);
103					throw new ToolAuthorizationError("Confirmation was cancelled or expired.", "deny");
104				}
105				return this.execute({
106					...input,
107					context: {
108						...input.context,
109						confirmationToken: challenge.id,
110						provenance: { ...input.context.provenance, userAuthorized: true },
111					},
112				});
113			}
114		}
