116		private issue(context: ToolExecutionContext, toolName: string, argumentDigest: string, risk: ToolRiskClass): ConfirmationChallenge {
117			const challenge: ConfirmationChallenge = {
118				id: crypto.randomUUID(), sessionId: context.sessionId, toolName, argumentDigest,
119				expiresAt: this.now() + this.ttlMs, documentRevision: context.documentRevision, risk,
120			};
121			this.challenges.set(challenge.id, challenge);
122			return challenge;
123		}
124	
125		private redeem(token: string, context: ToolExecutionContext, toolName: string, argumentDigest: string): void {
126			const challenge = this.challenges.get(token);
127			this.challenges.delete(token);
128			if (!challenge || challenge.expiresAt < this.now()) throw new ToolAuthorizationError("Confirmation is invalid or expired.", "deny");
129			if (challenge.sessionId !== context.sessionId || challenge.toolName !== toolName || challenge.argumentDigest !== argumentDigest || challenge.documentRevision !== context.documentRevision) {
