 81	/** Used by independently authorized transports so an approved call is not wrapped a second time. */
 82	export function executeRawKeatingTool(tool: AgentTool, args: any[]): Promise<unknown> {
 83		const execute = rawToolExecutions.get(tool as object);
 84		if (!execute) throw new Error(`No executable implementation for tool ${tool.name}.`);
 85		return execute(...args);
